; mult.asm - Multiply two numbers by repeated addition (the SSEM has no
; hardware multiplier). Put the factors on lines 30 and 31; when the machine
; stops, the product is on line 29. For example 6 * 7 = 42 and 20 * 15 = 300.
;
; This program was generated by AI (model: Mistral Large 4)
;
; Encoding notes:
; - Line 00 is a dummy: CI is pre-incremented, so execution starts at line 01.
; - JRP is indirect: to land on line T from a JRP on line L, store[S] must be
;   T - L - 1. Lines 24, 25 and 27 are those jump-target words.
; - The counter C is kept negated on line 23, so LDN 23 loads +C.
; - Line 23 (T) is used to negate the accumulator: STO 23 then LDN 23.

00 NUM 0     ;
01 LDN 31    ; A = -b
02 STO 23    ;   CN = -b, so the counter C = b
03 LDN 23    ; loop: A = C
04 SUB 26    ;   A = C - 1
05 CMP       ;   skip next if C < 1, i.e. the counter is exhausted
06 JRP 24    ;   C > 0 -> add (line 8)
07 JRP 25    ;   C <= 0 -> done (line 19)
08 LDN 29    ; add: A = -R
09 SUB 30    ;   A = -R - a = -(R + a)
10 STO 22    ;   T = -(R + a)
11 LDN 22    ;   A = R + a
12 STO 29    ;   R = R + a
13 LDN 23    ;   A = C
14 SUB 26    ;   A = C - 1
15 STO 22    ;   T = C - 1
16 LDN 22    ;   A = -(C - 1)
17 STO 23    ;   CN = -(C - 1), i.e. C = C - 1
18 JRP 27    ;   back to loop (line 3)
19 STP       ; done: R holds the product
20 NUM 0     ;
21 NUM 0     ;
22 NUM 0     ; T: temp, used to negate the accumulator
23 NUM 0     ; CN: counter, stored negated (-C)
24 NUM 1     ; jump word for line 06: 8 - 6 - 1
25 NUM 11    ; jump word for line 07: 19 - 7 - 1
26 NUM 1     ; ONE: constant 1
27 NUM -16   ; jump word for line 18: 3 - 18 - 1
28 NUM 0     ;
29 NUM 0     ; ---> result R: the product a * b
30 NUM 6     ; <--- a (input)
31 NUM 7     ; <--- b (input)
